bool ApprovedImage(const wchar_t*path)noexcept{try{HANDLE f=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_SEQUENTIAL_SCAN,nullptr);if(f==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER s{};bool ok=GetFileSizeEx(f,&s)&&s.QuadPart==kApprovedSize;std::vector<unsigned char>b(1<<20),all;DWORD n=0;while(ok&&ReadFile(f,b.data(),b.size(),&n,nullptr)&&n)all.insert(all.end(),b.begin(),b.begin()+n);CloseHandle(f);return ok&&Sha256(all.data(),static_cast<DWORD>(all.size()))==kApprovedHash;}catch(...){return false;}}
void Log(const char*event,const char*result)noexcept{if(g_report==INVALID_HANDLE_VALUE)return;char line[384]{};SYSTEMTIME t{};GetSystemTime(&t);int n=sprintf_s(line,"{\"timestampUtc\":\"%04u-%02u-%02uT%02u:%02u:%02u.%03uZ\",\"event\":\"%s\",\"profile\":\"dx9\",\"result\":\"%s\"}\n",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute,t.wSecond,t.wMilliseconds,event,result);if(n<=0)return;AcquireSRWLockExclusive(&g_logLock);DWORD w=0;WriteFile(g_report,line,n,&w,nullptr);FlushFileBuffers(g_report);ReleaseSRWLockExclusive(&g_logLock);}
