void ClearWorld(const char*reason)noexcept{const bool had=g_worldHandle.Present();g_worldHandle.Clear();if(had)Log("world_handle_cleared",reason);}
void __fastcall Processed1637(void*self,void*)noexcept{__try{auto*p=self?*reinterpret_cast<std::byte**>(static_cast<unsigned char*>(self)+0x404):nullptr;if(g_worldHandle.Capture(p,52,g_launchSession)==revora_world::Result::captured)Log("world_handle_captured","nonzero");else Log("world_handle_bridge_rejected","invalid_1637");}__except(EXCEPTION_EXECUTE_HANDLER){ClearWorld("exception");Log("world_handle_bridge_rejected","invalid_memory");}g_processed(self);}
void __fastcall OutgoingPacket(void*self,void*,void*object)noexcept{bool injected=false;__try{auto*p=object?reinterpret_cast<std::byte*>(static_cast<unsigned char*>(object)+4):nullptr;const auto size=p?*reinterpret_cast<std::uint16_t*>(p):0;const auto result=g_worldHandle.Inject(p,size,g_launchSession);injected=result==revora_world::Result::injected;if(injected)Log("world_handle_injected","opcode_2429_offset_4_width_4");else if(p&&size>=4&&*reinterpret_cast<std::uint16_t*>(p+2)==2429)Log("world_handle_bridge_rejected",result==revora_world::Result::rejected_expired?"expired":"invalid_2429");}__except(EXCEPTION_EXECUTE_HANDLER){ClearWorld("exception");Log("world_handle_bridge_rejected","invalid_memory");}g_outgoing(self,object);if(injected)Log("world_handle_cleared","consumed");}
